20: #include "crypt-port.h"
21: 
22: #include <errno.h>
23: #include <stdlib.h>
24: 
25: /* The internal storage area within struct crypt_data is used as
26:    follows.  We don't know what alignment the algorithm modules will
27:    need for their scratch data, so give it the maximum natural
28:    alignment.  Note that the C11 alignas() specifier can't be applied
29:    directly to a struct type, but it can be applied to the first field
30:    of a struct, which effectively forces alignment of the entire
31:    struct, since the first field must always have offset 0.  */
32: struct crypt_internal
33: {
34:   /* Alignment critical data members.  */
35:   char alignas (alignof (max_align_t)) alg_specific[ALG_SPECIFIC_SIZE];
36:   /* Not alignment critical data members.  */
37:   char output[CRYPT_OUTPUT_SIZE];
38: };
39: 
40: static_assert(sizeof (struct crypt_internal) + alignof (struct crypt_internal)
41:               <= CRYPT_DATA_INTERNAL_SIZE,
42:               "crypt_data.internal is too small for crypt_internal");
43: 
44: /* struct crypt_data is allocated by application code and contains
45:    only char-typed fields, so its 'internal' field may not be
46:    sufficiently aligned.  */
47: static inline struct crypt_internal *
48: get_internal (struct crypt_data *data)
49: {
50:   uintptr_t internalp = (uintptr_t) data->internal;
51:   const uintptr_t align = alignof (struct crypt_internal);
52:   internalp = (internalp + align - 1) & ~(align - 1);
53:   return (struct crypt_internal *)internalp;
54: }
55: 
56: typedef void (*crypt_fn) (const char *phrase, size_t phr_size,
57:                           const char *setting, size_t set_size,
58:                           uint8_t *output, size_t out_size,
59:                           void *scratch, size_t scr_size);
60: 
61: typedef void (*gensalt_fn) (unsigned long count,
62:                             const uint8_t *rbytes, size_t nrbytes,
63:                             uint8_t *output, size_t output_size);
64: 
65: struct hashfn
66: {
67:   const char *prefix;
68:   size_t plen;
69:   crypt_fn crypt;
70:   gensalt_fn gensalt;
71:   /* The type of this field is unsigned char to ensure that it cannot
72:      be set larger than the size of an internal buffer in crypt_gensalt_rn.  */
73:   unsigned char nrbytes;
74:   unsigned char is_strong;
75: };
76: 
77: static const struct hashfn hash_algorithms[] =
78: {
79:   HASH_ALGORITHM_TABLE_ENTRIES
80: };
81: 
82: #if INCLUDE_descrypt || INCLUDE_bigcrypt
83: static int
84: is_des_salt_char (char c)
85: {
86:   return ((c >= 'a' && c <= 'z') ||
87:           (c >= 'A' && c <= 'Z') ||
88:           (c >= '0' && c <= '9') ||
89:           c == '.' || c == '/');
90: }
91: #endif
92: 
93: static const struct hashfn *
94: get_hashfn (const char *setting)
95: {
96:   const struct hashfn *h;
97:   for (h = hash_algorithms; h->prefix; h++)
98:     {
99:       if (h->plen > 0)
100:         {
101:           if (!strncmp (setting, h->prefix, h->plen))
102:             return h;
103:         }
104: #if INCLUDE_descrypt || INCLUDE_bigcrypt
105:       else
106:         {
107:           if (setting[0] == '\0' ||
108:               (is_des_salt_char (setting[0]) && is_des_salt_char (setting[1])))
109:             return h;
110:         }
111: #endif
112:     }
113:   return 0;
114: }
115: 
116: /* Check a setting string for generic validity, according to the rule
117:    stated in crypt(5):
118: 
119:       "Hashed passphrases are always entirely printable ASCII, and do
120:       not contain any whitespace or the characters ':', ';', '*', '!',
121:       or '\\'.  (These characters are used as delimiters and special
122:       markers in the passwd(5) and shadow(5) files.)"
123: 
124:    There is a precautionary case for rejecting additional ASCII
125:    punctuation, particularly other characters often given syntactic
126:    significance in configuration files, such as " ' and #.  However,
127:    this check didn't used to exist at all, and some of the hash
128:    function implementations don't restrict the set of byte values they
129:    they will accept in their setting strings (particularly in the salt
130:    component) either.  Thus, to maintain compatibility with the widest
131:    variety of existing hashed passphrases, we are only enforcing the
132:    documented rule for now.
133: 
134:    See <https://github.com/besser82/libxcrypt/issues/135> for
135:    additional discussion.  */
136: static int
137: check_badsalt_chars (const char *setting)
138: {
139:   size_t i;
140: 
141:   for (i = 0; setting[i] != '\0'; i++)
142:     if ((unsigned char) setting[i] <= 0x20 ||
143:         (unsigned char) setting[i] >= 0x7f)
144:       return 1;
145: 
146:   return strcspn (setting, "!*:;\\") != i;
147: }
148: 
149: static void
150: do_crypt (const char *phrase, const char *setting, struct crypt_data *data)
151: {
152:   struct crypt_internal *cint = get_internal (data);
153:   memset (cint->output, 0, sizeof cint->output);
154:   make_failure_token (setting, cint->output, sizeof cint->output);
155: 
156:   if (!phrase || !setting)
157:     {
158:       errno = EINVAL;
159:       goto out;
160:     }
161:   /* Do these strlen() calls before reading prefixes of either
162:      'phrase' or 'setting', so we get a predictable crash if they are
163:      not valid strings.  */
164:   size_t phr_size = strlen (phrase);
165:   size_t set_size = strlen (setting);
166:   if (phr_size >= CRYPT_MAX_PASSPHRASE_SIZE)
167:     {
168:       errno = ERANGE;
169:       goto out;
170:     }
171:   if (check_badsalt_chars (setting))
172:     {
173:       errno = EINVAL;
174:       goto out;
175:     }
176: 
177:   const struct hashfn *h = get_hashfn (setting);
178:   if (!h)
179:     {
180:       /* Unrecognized hash algorithm */
181:       errno = EINVAL;
182:       goto out;
183:     }
184: 
185:   h->crypt (phrase, phr_size, setting, set_size,
186:             (unsigned char *) cint->output, sizeof cint->output,
187:             cint->alg_specific, sizeof cint->alg_specific);
188: 
189: out:
190:   strcpy_or_abort (data->output, sizeof data->output, cint->output);
191:   explicit_bzero (data->internal, sizeof data->internal);
192:   explicit_bzero (data->reserved, sizeof data->reserved);
193:   data->initialized = 0;
194: }
195: 
196: #if INCLUDE_crypt_rn
197: char *
198: crypt_rn (const char *phrase, const char *setting, void *data, int size)
199: {
200:   if (size < (int) sizeof (struct crypt_data))
201:     {
202:       errno = ERANGE;
203:       make_failure_token (setting, data, size);
204:       return 0;
205:     }
206: 
207:   struct crypt_data *p = data;
208:   do_crypt (phrase, setting, p);
